-- =====================================================================
-- 0009 · Usernames, for public profiles
--
-- The first three statements were generated by the Better Auth CLI
-- (npx auth@1.7.12 generate) for the username plugin in
-- app/prototypes/inspiration-library/lib/auth.ts:
--
--   username         always lower case; unique, so two people can't share one
--   displayUsername  how you typed it ("Mia_Studio"), for showing
--
-- Both are empty for accounts made before this (and for Google sign-ups)
-- until you choose a username on your library's home page.
-- =====================================================================

alter table "user" add column "username" text;

alter table "user" add column "displayUsername" text;

create unique index "user_username_uidx" on "user" ("username");

-- A second lock behind the plugin's own checks: whatever writes to the
-- table, a username is 3–30 lower-case letters, numbers, _ or . (the
-- plugin's rules, after it lower-cases it), so it's always safe in a web
-- address like /u/<username>.
alter table "user" add constraint user_username_format check ("username" ~ '^[a-z0-9_.]{3,30}$');
